mapper.select:
SELECT id, shop_name, address, phone, business_status, notice, create_time, update_time
FROM merchant_shop
WHERE id = #{id}

mapper.update:
UPDATE merchant_shop
SET shop_name = #{shop.shopName},
    address = #{shop.address},
    phone = #{shop.phone},
    notice = #{shop.notice}
WHERE id = #{id}

UPDATE merchant_shop
SET business_status = #{businessStatus}
WHERE id = #{id}
